// <editor-fold defaultstate="collapsed" desc="imports">
import React from "react";
import {observer} from 'mobx-react';
import {computed, observable} from "mobx";

import {Dates} from 'utils/Utils';
import {AProfileDialog} from 'components/dialogs';
import {ProfileField, RowOrgs} from 'components/inputs';
import {FormControls, Row} from 'components/FormComponents';
import {NewEmployeeListTable, NewPPEItemListTable} from 'components/FormTableComponents';

import style from "./ProfileTeamDialog.lazy.css";
import {CircularProgress} from "@mui/material";
import findByIdTeam from "mutations/all/Team/findByIdTeam";
// </editor-fold>

// <editor-fold defaultstate="collapsed" desc="Dialog">
@observer
class ProfileDialog extends AProfileDialog {
	pageKey = "ProfileTeamDialog";
	findById = findByIdTeam;

	constructor(props) {
		super(props, style);
	}

	title() {
		return "Team";
	}

	get topButtonsHiddenDelete() {
		return true;
	}

	get controls() {
		return Controls;
	}
}

// </editor-fold>

@observer
class Controls extends React.Component {

	// <editor-fold defaultstate="collapsed" desc="fields">
	@observable
	state = {
		item: null,
	};
	// </editor-fold>

	// <editor-fold defaultstate="collapsed" desc="constructor">
	constructor(props) {
		super(props);
	}

	// </editor-fold>

	@computed get item() {
		return this.state.item;
	}

	// <editor-fold defaultstate="collapsed" desc="render">
	render() {
		if (!this.item) {
			return <CircularProgress className="fixed-center"/>;
		}

		const {
			props: {
				onFormNext, onFormBack, onFormOpen,
				dialog: {renderProfileCover}
			},
			item: {
				id, data: {
					created_at,
					site, project, client,
					supervisor,
					name, status,
					//
					list,
					//
					ppe_list
				}
			}
		} = this;

		return <FormControls>
			<RowOrgs
				readonly
				client={client}
				project={project}
				site={site}
				onFormOpen={onFormOpen}
				onFormBack={onFormBack}
				onFormNext={onFormNext}
			>
				<Row
					rendered
					idx={1}
					title="1. Team Details"
				>
					<ProfileField title="Supervisor" value={supervisor}
					              renderer={v => (v.lname || v.data.lname) + " " + (v.fname || v.data.fname)}
					              className="col-lg-12"/>
					<ProfileField title="Team Name" value={name} className="col-lg-12"/>
					<ProfileField title="Status" value={status} className="col-lg-12"/>
				</Row>
			</RowOrgs>
			<Row
				rendered
				idx={2}
				title="2. Team Members"
				onFormOpen={onFormOpen}
				onFormNext={onFormNext}
				onFormBack={onFormBack}
			>
				<NewEmployeeListTable name="list" defaultValue={[...(list || [])]} readonly/>
			</Row>
			<Row
				rendered
				idx={3}
				title="3. PPE Required"
				onFormOpen={onFormOpen}
				onFormBack={onFormBack}
			>
				<NewPPEItemListTable name="ppe_list" defaultValue={[...(ppe_list || [])]} readonly/>
			</Row>
		</FormControls>;
	}

	// </editor-fold>

}

export default ProfileDialog;
